#!/usr/bin/env bash
#
# Point a console's SD card back at GRID0+ after it has been in Nextendo
# mode (or any other mode Prelude manages). Prelude's own mode switch rewrites
# three things that have nothing to do with Nextendo specifically -- it just
# always resets them to its own defaults -- so switching back means putting
# GRID0+'s versions back:
#
#   1. atmosphere/hosts/{emummc,sysmmc}.txt -- Prelude replaces these with its
#      own wildcard *.nintendo.* redirect. GRID0+ needs its own, narrower
#      host list back (switch/hosts.txt, generated by 'make gen-hosts').
#
#   2. atmosphere/config/system_settings.ini's add_defaults_to_dns_hosts --
#      Prelude sets this to 0x1. GRID0+ requires 0x0, or Atmosphere layers
#      its own built-in redirect list on top of ours, outside our control.
#
#   3. The browser's own CA bundles, under
#      atmosphere/contents/0100000000000803/romfs/{0/browser,browser}/ --
#      Prelude resets both RootCaEtc.pem and RootCaSdkAdditional.pem to its
#      own clean copy (containing only Nextendo's CA) every time it applies
#      Nextendo mode. GRID0+'s own CA (certs/rootCA.pem) has to be
#      re-appended, or the browser-based Nintendo Account link page's TLS
#      connection fails with no useful error.
#
# What this script deliberately does NOT touch: the disable_ca_verification
# exefs patch. GRID0+ adopted the same patch Prelude uses for its own
# nn::ssl/libcurl-based clients (nnAccount, nnDauth), so it stays installed
# either way -- see switch/README.md.
#
# Safe to run more than once: every step checks the current state first and
# only changes what is actually wrong.
set -euo pipefail

REPO_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
SD="${1:-${SD_MOUNT:-/run/media/$(logname 2>/dev/null || echo "$USER")/SWITCH SD}}"

if [ ! -d "$SD" ]; then
    echo "error: SD card not found at '$SD'" >&2
    echo "usage: $0 [path-to-sd-card-mount]" >&2
    echo "       or set SD_MOUNT" >&2
    exit 1
fi

echo "== GRID0+ mode: $SD =="

# ---------------------------------------------------------------------------
# 1. Host redirection.

echo "-- regenerating switch/hosts.txt"
make -C "$REPO_DIR" gen-hosts >/dev/null

HOSTS_SRC="$REPO_DIR/switch/hosts.txt"
if [ ! -s "$HOSTS_SRC" ]; then
    echo "error: $HOSTS_SRC is missing or empty after gen-hosts" >&2
    exit 1
fi

for dst in "$SD/atmosphere/hosts/emummc.txt" "$SD/atmosphere/hosts/sysmmc.txt"; do
    mkdir -p "$(dirname "$dst")"
    if cmp -s "$HOSTS_SRC" "$dst" 2>/dev/null; then
        echo "   $dst already up to date"
    else
        cp "$HOSTS_SRC" "$dst"
        echo "   wrote $dst"
    fi
done

# ---------------------------------------------------------------------------
# 2. system_settings.ini: add_defaults_to_dns_hosts = 0x0.

INI="$SD/atmosphere/config/system_settings.ini"
if [ ! -f "$INI" ]; then
    echo "error: $INI does not exist -- is this console set up with Atmosphere at all?" >&2
    exit 1
fi

if grep -qx "add_defaults_to_dns_hosts = u8!0x0" "$INI"; then
    echo "-- add_defaults_to_dns_hosts already 0x0"
elif grep -q "^add_defaults_to_dns_hosts" "$INI"; then
    sed -i 's/^add_defaults_to_dns_hosts.*/add_defaults_to_dns_hosts = u8!0x0/' "$INI"
    echo "-- set add_defaults_to_dns_hosts = u8!0x0 (was set to something else)"
elif grep -q "^; add_defaults_to_dns_hosts" "$INI"; then
    sed -i 's/^; add_defaults_to_dns_hosts.*/add_defaults_to_dns_hosts = u8!0x0/' "$INI"
    echo "-- uncommented and set add_defaults_to_dns_hosts = u8!0x0"
else
    echo "error: no add_defaults_to_dns_hosts line found in $INI (commented or not) -- refusing to guess where to add one" >&2
    exit 1
fi

# ---------------------------------------------------------------------------
# 3. Browser CA bundles.

CA_SRC="$REPO_DIR/certs/rootCA.pem"
if [ ! -s "$CA_SRC" ]; then
    echo "error: $CA_SRC is missing -- run 'make gen-certs' first" >&2
    exit 1
fi

# Matched by subject, not by byte-for-byte file content: the bundle also
# holds the console's/Nintendo's own CAs, which this must never touch.
CA_MARK="CN=SwitchNet Local CA"

append_ca() {
    local f="$1"
    if [ ! -f "$f" ]; then
        echo "   $f does not exist, skipping"
        return
    fi
    if openssl storeutl -noout -certs -text "$f" 2>/dev/null | grep -qF "$CA_MARK"; then
        echo "   $f already has GRID0+'s CA"
        return
    fi
    # Ensure the file ends with a newline before appending, or the two PEM
    # blocks concatenate onto one line and neither parses.
    [ -n "$(tail -c1 "$f")" ] && echo >> "$f"
    cat "$CA_SRC" >> "$f"
    echo "   appended GRID0+'s CA to $f"
}

for f in \
    "$SD/atmosphere/contents/0100000000000803/romfs/0/browser/RootCaEtc.pem" \
    "$SD/atmosphere/contents/0100000000000803/romfs/browser/RootCaEtc.pem" \
    "$SD/atmosphere/contents/0100000000000803/romfs/0/browser/RootCaSdkAdditional.pem" \
    "$SD/atmosphere/contents/0100000000000803/romfs/browser/RootCaSdkAdditional.pem"; do
    append_ca "$f"
done

echo "== done =="
echo "Reboot the console for the hosts file and system_settings.ini changes to take effect."
